ed fix for both is a semver-major\ndowngrade, rejected.","tree":{"sha":"c61a9eba6160d9f8944ead62e1588073fd4eefeb","url":"https://api.github.com/repos/Vadymk95/template-1/git/trees/c61a9eba6160d9f8944ead62e1588073fd4eefeb"},"url":"https://api.github.com/repos/Vadymk95/template-1/git/commits/6bba9043ff23b2e244a071e78d3e66f435ccb21d","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/70842045?v=4","events_url":"https://api.github.com/users/Vadymk95/events{/privacy}","followers_url":"https://api.github.com/users/Vadymk95/followers","following_url":"https://api.github.com/users/Vadymk95/following{/other_user}","gists_url":"https://api.github.com/users/Vadymk95/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/Vadymk95","id":70842045,"login":"Vadymk95","node_id":"MDQ6VXNlcjcwODQyMDQ1","organizations_url":"https://api.github.com/users/Vadymk95/orgs","received_events_url":"https://api.github.com/users/Vadymk95/received_events","repos_url":"https://api.github.com/users/Vadymk95/repos","site_admin":false,"starred_url":"https://api.github.com/users/Vadymk95/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/Vadymk95/subscriptions","type":"User","url":"https://api.github.com/users/Vadymk95","user_view_type":"public"},"html_url":"https://github.com/Vadymk95/template-1/commit/6bba9043ff23b2e244a071e78d3e66f435ccb21d","node_id":"C_kwDOQT0KedoAKDZiYmE5MDQzZmYyM2IyZTI0NGEwNzFlNzhkM2U2NmY0MzVjY2IyMWQ","parents":[{"html_url":"https://github.com/Vadymk95/template-1/commit/cf1ee6fc3e94b111b5a48229a54414b58d56002a","sha":"cf1ee6fc3e94b111b5a48229a54414b58d56002a","url":"https://api.github.com/repos/Vadymk95/template-1/commits/cf1ee6fc3e94b111b5a48229a54414b58d56002a"}],"sha":"6bba9043ff23b2e244a071e78d3e66f435ccb21d","url":"https://api.github.com/repos/Vadymk95/template-1/commits/6bba9043ff23b2e244a071e78d3e66f435ccb21d"},{"author